// ScheduledFuture 的默认实现（模板，header-only）。
// 记录计划执行时间，由调度线程到期时调用 run() 真正执行任务。
// cancel 与 run 共用一把锁，保证 promise 只被设置一次。
template<typename T>
class SimpleScheduledFuture : public ScheduledFuture<T> {
public:
    SimpleScheduledFuture(std::function<T()> task, long delay, TimeUnit unit)
        : task_(std::move(task)),
          promise_(std::make_shared<std::promise<T>>()),
          future_(promise_->get_future().share()),
          runAt_(std::chrono::steady_clock::now() +
                 std::chrono::nanoseconds(TimeUnit::NANOSECONDS.convert(delay, unit))) {}

    // 计划执行时间点（调度队列据此排序）
    std::chrono::steady_clock::time_point runAt() const { return runAt_; }

    // 到期后由调度线程调用：执行任务并写入结果；已取消则直接跳过
    void run() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;
        }
        try {
            T value = task_();
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;  // 执行期间被取消
            done_ = true;
            promise_->set_value(std::move(value));
        } catch (...) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;
            done_ = true;
            promise_->set_exception(std::current_exception());
        }
    }

    // 阻塞获取结果；被取消或任务异常时重新抛出
    T get() override { return future_.get(); }

    // 取消：未开始时标记取消并以异常完成，后续 run() 变为空操作
    bool cancel(bool /*mayInterruptIfRunning*/) override {
        std::lock_guard<std::mutex> lock(mutex_);
        if (done_ || cancelled_) return false;
        cancelled_ = true;
        done_ = true;
        promise_->set_exception(
            std::make_exception_ptr(std::runtime_error("ScheduledFuture 已取消")));
        return true;
    }

    bool isDone() override {
        std::lock_guard<std::mutex> lock(mutex_);
        return done_;
    }

    // 剩余延迟：内部以纳秒计，换算到 unit（到期后 <= 0）
    long getDelay(TimeUnit unit) const override {
        auto nanos = std::chrono::duration_cast<std::chrono::nanoseconds>(
                         runAt_ - std::chrono::steady_clock::now())
                         .count();
        return unit.convert(static_cast<long>(nanos), TimeUnit::NANOSECONDS);
    }

private:
    std::function<T()> task_;
    std::shared_ptr<std::promise<T>> promise_;
    std::shared_future<T> future_;
    std::chrono::steady_clock::time_point runAt_;
    std::mutex mutex_;
    bool cancelled_ = false;
    bool done_ = false;
};

// void 特化：对应 Java 中 schedule(Runnable, long, TimeUnit) 的无返回值任务
template<>
class SimpleScheduledFuture<void> : public ScheduledFuture<void> {
public:
    SimpleScheduledFuture(std::function<void()> task, long delay, TimeUnit unit)
        : task_(std::move(task)),
          promise_(std::make_shared<std::promise<void>>()),
          future_(promise_->get_future().share()),
          runAt_(std::chrono::steady_clock::now() +
                 std::chrono::nanoseconds(TimeUnit::NANOSECONDS.convert(delay, unit))) {}

    std::chrono::steady_clock::time_point runAt() const { return runAt_; }

    void run() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;
        }
        try {
            task_();
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;
            done_ = true;
            promise_->set_value();
        } catch (...) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (cancelled_ || done_) return;
            done_ = true;
            promise_->set_exception(std::current_exception());
        }
    }

    void get() override { future_.get(); }

    bool cancel(bool /*mayInterruptIfRunning*/) override {
        std::lock_guard<std::mutex> lock(mutex_);
        if (done_ || cancelled_) return false;
        cancelled_ = true;
        done_ = true;
        promise_->set_exception(
            std::make_exception_ptr(std::runtime_error("ScheduledFuture 已取消")));
        return true;
    }

    bool isDone() override {
        std::lock_guard<std::mutex> lock(mutex_);
        return done_;
    }

    long getDelay(TimeUnit unit) const override {
        auto nanos = std::chrono::duration_cast<std::chrono::nanoseconds>(
                         runAt_ - std::chrono::steady_clock::now())
                         .count();
        return unit.convert(static_cast<long>(nanos), TimeUnit::NANOSECONDS);
    }

private:
    std::function<void()> task_;
    std::shared_ptr<std::promise<void>> promise_;
    std::shared_future<void> future_;
    std::chrono::steady_clock::time_point runAt_;
    std::mutex mutex_;
    bool cancelled_ = false;
    bool done_ = false;
};

