// java.util.concurrent.ScheduledExecutorService 桩。
// 在 ExecutorService 之上增加一个调度线程：
// 延迟任务进按执行时间排序的优先队列，调度线程用 condition_variable::wait_until
// 等到队首任务到期后触发其执行。shutdown 时丢弃未到期任务（桩级简化）。
class ScheduledExecutorService : public ExecutorService {
public:
    explicit ScheduledExecutorService(std::size_t workers = std::thread::hardware_concurrency());
    ~ScheduledExecutorService() override;

    // 延迟调度带返回值任务（对应 Java schedule(Callable, long, TimeUnit)）
    template<typename T>
    std::shared_ptr<ScheduledFuture<T>> schedule(std::function<T()> callable, long delay,
                                                 TimeUnit unit) {
        auto sf = std::make_shared<sitp_stubs_detail::SimpleScheduledFuture<T>>(
            std::move(callable), delay, unit);
        enqueueDelayed(sf->runAt(), [sf]() { sf->run(); });
        return sf;
    }

    // 延迟调度无返回值任务（对应 Java schedule(Runnable, long, TimeUnit)）。
    // 非模板重载，优先级高于上面 T=void 的模板实例化。
    std::shared_ptr<ScheduledFuture<void>> schedule(std::function<void()> command, long delay,
                                                    TimeUnit unit) {
        auto sf = std::make_shared<sitp_stubs_detail::SimpleScheduledFuture<void>>(
            std::move(command), delay, unit);
        enqueueDelayed(sf->runAt(), [sf]() { sf->run(); });
        return sf;
    }

    // 关闭：先停调度线程再停底层线程池
    void shutdown() override;

private:
    // 延迟队列元素：执行时间点 + 序号（稳定排序）+ 到期触发器
    struct DelayedTask {
        std::chrono::steady_clock::time_point runAt;
        std::uint64_t seq;
        std::function<void()> trigger;
    };
    // 最早执行的任务在堆顶
    struct LaterFirst {
        bool operator()(const DelayedTask& a, const DelayedTask& b) const {
            if (a.runAt != b.runAt) return a.runAt > b.runAt;
            return a.seq > b.seq;
        }
    };

    void enqueueDelayed(std::chrono::steady_clock::time_point runAt,
                        std::function<void()> trigger);
    void schedulerLoop();

    std::mutex schedMutex_;
    std::condition_variable schedCv_;
    std::priority_queue<DelayedTask, std::vector<DelayedTask>, LaterFirst> delayed_;
    std::thread scheduler_;
    std::uint64_t seq_ = 0;
    bool schedShutdown_ = false;
};

cpp_code:
#include "ScheduledExecutorService.h"

ScheduledExecutorService::ScheduledExecutorService(std::size_t workers)
    : ExecutorService(workers), scheduler_([this]() { schedulerLoop(); }) {}

ScheduledExecutorService::~ScheduledExecutorService() {
    shutdown();  // 停调度线程与底层线程池（幂等）
    if (scheduler_.joinable()) scheduler_.join();
}

void ScheduledExecutorService::shutdown() {
    {
        std::lock_guard<std::mutex> lock(schedMutex_);
        schedShutdown_ = true;
    }
    schedCv_.notify_all();
    ExecutorService::shutdown();
}

void ScheduledExecutorService::enqueueDelayed(
    std::chrono::steady_clock::time_point runAt, std::function<void()> trigger) {
    {
        std::lock_guard<std::mutex> lock(schedMutex_);
        if (schedShutdown_)
            throw std::runtime_error("ScheduledExecutorService 已 shutdown，拒绝新任务");
        delayed_.push(DelayedTask{runAt, seq_++, std::move(trigger)});
    }
    schedCv_.notify_all();
}

void ScheduledExecutorService::schedulerLoop() {
    std::unique_lock<std::mutex> lock(schedMutex_);
    for (;;) {
        if (delayed_.empty()) {
            // shutdown 且没有未到期任务时退出（未到期任务随 shutdown 丢弃）
            if (schedShutdown_) return;
            schedCv_.wait(lock);
            continue;
        }
        auto now = std::chrono::steady_clock::now();
        if (delayed_.top().runAt > now) {
            // 等到队首任务到期；被唤醒（新任务/shutdown/虚假唤醒）后重新检查
            schedCv_.wait_until(lock, delayed_.top().runAt);
            continue;
        }
        // 队首任务已到期：取出并触发执行（任务本体在调度线程内同步运行）
        DelayedTask task = delayed_.top();
        delayed_.pop();
        lock.unlock();
        try {
            task.trigger();
        } catch (...) {
            // 触发异常不传播，避免拖垮调度线程
        }
        lock.lock();
    }
}
